const sigrok = require("..");

const CSV = [
	"; CSV generated by libsigrok 0.6.0",
	"; Channels (3/13): D0, D1, A0",
	"; Samplerate: 200 kHz",
	"logic,logic,V DC",
	"1,0,-10",
	"0,1,2.5",
	""
].join("\n");

describe("sigrok csv", () => {
	test("parses channel names, units, samplerate and columns", () => {
		const parsed = sigrok._parseCsv(CSV);
		expect(parsed.samplerate).toBe(200000);
		expect(parsed.columns.map((c) => c.name)).toEqual(["D0", "D1", "A0"]);
		expect(parsed.columns[2]).toEqual({ name: "A0", unit: "V DC", values: [-10, 2.5] });
	});
});
